package com.lendup.reservas.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="registro_auditoria") public class AuditEntity { @Id private UUID id; @Column(name="aggregate_type",nullable=false) private String aggregateType; @Column(name="aggregate_id",nullable=false) private UUID aggregateId; @Column(nullable=false) private String action; @Column(name="previous_state") private String previousState; @Column(name="new_state",nullable=false) private String newState; @Column(name="actor_id") private UUID actorId; @Column(name="correlation_id",nullable=false) private String correlationId; @Column(name="occurred_at",nullable=false) private Instant occurredAt; protected AuditEntity(){} public AuditEntity(UUID id,String t,UUID a,String action,String prev,String next,UUID actor,String corr,Instant at){this.id=id;aggregateType=t;aggregateId=a;this.action=action;previousState=prev;newState=next;actorId=actor;correlationId=corr;occurredAt=at;} }
